const usedUrls = new Set(
  $('Lire historique').all().map(item => (item.json.url || '').trim())
);

const nouveaux = $input.all().filter(item => !usedUrls.has((item.json.link || '').trim()));

nouveaux.sort((a, b) => new Date(b.json.pubDate || 0) - new Date(a.json.pubDate || 0));

return nouveaux.slice(0, 20);

const articles = $input.all().map(item => item.json);
const blocs = $('Blocs récurrents').first().json;

const now = new Date();
const moisAnnee = now.toLocaleDateString('fr-FR', { month: 'long', year: 'numeric', timeZone: 'Europe/Paris' });

const systemPrompt = "Tu es le redacteur de la newsletter mensuelle d’un professionnel de l’immobilier (agent, plus un reseau d’apporteurs et de consultants). Tu selectionnes les meilleurs articles par theme et rediges une synthese courte, factuelle, sans jargon, avec un ton professionnel et chaleureux, destinee a des particuliers proprietaires ou vendeurs. Reponds UNIQUEMENT avec un objet JSON valide, sans texte autour, au format exact suivant : {\"sections\":[{\"category\":\"...\",\"categoryLabel\":\"...\",\"titre\":\"...\",\"synthese\":\"...\",\"source_url\":\"...\"}],\"intro_apporteur\":\"...\",\"intro_recrutement\":\"...\"}. Choisis au maximum 1 a 2 articles par categorie parmi ceux fournis, uniquement s’ils sont pertinents. intro_apporteur et intro_recrutement sont une phrase d’accroche originale et renouvelee, qui introduit les blocs fixes fournis ci-dessous sans en changer le fond.";

const userPrompt = JSON.stringify({
  mois: moisAnnee,
  articles_disponibles: articles,
  bloc_apporteur_existant: blocs.texte_apporteur,
  bloc_recrutement_existant: blocs.texte_recrutement,
});

return [{
  json: {
    moisAnnee,
    claudeRequestBody: {
      model: 'claude-sonnet-4-5',
      max_tokens: 4000,
      system: systemPrompt,
      messages: [
        { role: 'user', content: userPrompt },
      ],
    },
  },
}];

const raw = ($json.content && $json.content[0] && $json.content[0].text) || '';
const cleaned = raw.trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();

let data;
try {
  data = JSON.parse(cleaned);
} catch (e) {
  throw new Error('Reponse Claude non parseable en JSON : ' + raw);
}

return [{ json: data }];

const data = $json;
const blocs = $('Blocs récurrents').first().json;
const moisAnnee = $('Préparer le prompt').first().json.moisAnnee;

const lignes = [];
lignes.push('NEWSLETTER IMMOBILIÈRE - ' + moisAnnee.toUpperCase());
lignes.push('');

for (const section of data.sections || []) {
  lignes.push('— ' + (section.categoryLabel || section.category).toUpperCase() + ' —');
  lignes.push(section.titre || '');
  lignes.push(section.synthese || '');
  if (section.source_url) lignes.push('Source : ' + section.source_url);
  lignes.push('');
}

lignes.push('— DEVENIR APPORTEUR D’AFFAIRES —');
lignes.push(data.intro_apporteur || '');
lignes.push(blocs.texte_apporteur || '');
lignes.push('');

lignes.push('— REJOINDRE L’ÉQUIPE —');
lignes.push(data.intro_recrutement || '');
lignes.push(blocs.texte_recrutement || '');

return [{
  json: {
    titreDoc: 'Newsletter immobilière - ' + moisAnnee,
    texteFinal: lignes.join('\n'),
    urlsSelectionnees: (data.sections || []).map(s => s.source_url).filter(Boolean),
  },
}];

const data = $json;
const today = new Date().toISOString().slice(0, 10);
return (data.urlsSelectionnees || []).map(url => ({ json: { url, date: today } }));
